Model":"SINGLE_GROUP","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":16,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"IOA-289 in combination with gemcitabine/nab-paclitaxel","type":"EXPERIMENTAL","interventionNames":["Drug: IOA-289"]}],"interventions":[{"type":"DRUG","name":"IOA-289","description":"IOA-289 will be administered orally twice daily (BID), starting from C0D1. Gemcitabine and nab-paclitaxel will be administrated by IV infusion, weekly for 3 weeks of a 4 week cycle starting at C1D1.","armGroupLabels":["IOA-289 in combination with gemcitabine/nab-paclitaxel"],"otherNames":["gemcitabine","nab-paclitaxel","Abraxane"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Incidence of treatment-emergent adverse events [Safety and Tolerability]","description":"Number of participants with treatment-related adverse events as assessed by CTCAE v5.0","timeFrame":"Adverse event assessment will be assessed by CTCAE v5.0, through study completion, an average of 1 year."}],"secondaryOutcomes":[{"measure":"Cmax","description":"Peak plasma concentration","timeFrame":"at Cycle 0 Day 1 (pre-dose and 1/2/3-4/6-8hrs post-dose), and predose for Cycle 0 Day 7, Cycle 1 Day 1, Cycle 1 Day 8, Cycle 1 Day 15 and from Cycle 2 onwards Day 1 and End of Treatment. Cycle 0 is 7 days and Cycle 1 and onwards is 28 days."},{"measure":"Cmin","description":"Minimum observed plasma concentration","timeFrame":"at Cycle 0 Day 1 (pre-dose and 1/2/3-4/6-8hrs post-dose), and predose for Cycle 0 Day 7, Cycle 1 Day 1, Cycle 1 Day 8, Cycle 1 Day 15 and from Cycle 2 onwards Day 1 and End of Treatment. Cycle 0 is 7 days and Cycle 1 and onwards is 28 days."},{"measure":"t½","description":"Terminal elimination half-life","timeFrame":"at Cycle 0 Day 1 (pre-dose and 1/2/3-4/6-8hrs post-dose), and predose for Cycle 0 Day 7, Cycle 1 Day 1, Cycle 1 Day 8, Cycle 1 Day 15 and from Cycle 2 onwards Day 1 and End of Treatment. Cycle 0 is 7 days and Cycle 1 and onwards is 28 days."},{"measure":"tmax","description":"Time of the maximum observed plasma concentration","timeFrame":"at Cycle 0 Day 1 (pre-dose and 1/2/3-4/6-8hrs post-dose), and predose for Cycle 0 Day 7, Cycle 1 Day 1, Cycle 1 Day 8, Cycle 1 Day 15 and from Cycle 2 onwards Day 1 and End of Treatment. Cycle 0 is 7 days and Cycle 1 and onwards is 28 days."},{"measure":"AUC0-t","description":"Area under the plasma concentration-time curve from time zero to the time of the last quantifiable concentration","timeFrame":"at Cycle 0 Day 1 (pre-dose and 1/2/3-4/6-8hrs post-dose), and predose for Cycle 0 Day 7, Cycle 1 Day 1, Cycle 1 Day 8, Cycle 1 Day 15 and from Cycle 2 onwards Day 1 and End of Treatment. Cycle 0 is 7 days and Cycle 1 and onwards is 28 days."},{"measure":"AUC0-∞","description":"Area under the plasma concentration-time curve from time zero extrapolated to infinity","timeFrame":"at Cycle 0 Day 1 (pre-dose and 1/2/3-4/6-8hrs post-dose), and predose for Cycle 0 Day 7, Cycle 1 Day 1, Cycle 1 Day 8, Cycle 1 Day 15 and from Cycle 2 onwards Day 1 and End of Treatment. Cycle 0 is 7 days and Cycle 1 and onwards is 28 days."},{"measure":"BED","description":"Define the biologically effective dose (BED) of IOA-289 based on available parameters","timeFrame":"for an average of 6 months"},{"measure":"CA19-9","description":"Assess changes of CA19-9 levels compared to baseline","timeFrame":"for an average of 6 months"},{"measure":"LPA","description":"Determine the PD activity of IOA-289, incl levels of LPA","timeFrame":"for an average of 6 months"},{"measure":"Preliminary efficacy","description":"Document preliminary signs of clinical efficacy of IOA-289 when given in combination with gemcitabine/nab-paclitaxel (e.g. overall response rate \[ORR\], duration of response \[DOR\], disease control rate (DCR), progression-free survival \[PFS\], and overall survival \[OS\] using RECIST v1.1)","timeFrame":"Imaging for RECIST assessment will start at C2D1 ±3 Days and repeated every 8 Weeks (56 ± 5Days) until disease progression."},{"measure":"Overall response rate [ORR]","description":"ORR defined as percentage of patients with a CR or PR based on appropriate radiographic imaging and consistent with RECIST 1.1","timeFrame":"for an average of 6 months"},{"measure":"Disease control rate [DCR]","description":"DCR is defined as the combined percentage of patients with radiographic CR, PR and SD at different time points","timeFrame":"for an average of 6 months"},{"measure":"Duration of response [DOR]","description":"DOR defined as time from first documented evidence of CR or PR until disease progression or death from any cause among patients who achieve objective response","timeFrame":"for an average of 6 months"},{"measure":"Progression free survival [PFS]","description":"PFS defined as the time from the date of the first dose of study treatment until the earliest date of disease progression as determined by radiographic disease assessment","timeFrame":"for an average of 6 months"},{"measure":"Overall survival [OS]","description":"OS defined as the time from the date of the first dose of study treatment until death from any cause.","timeFrame":"for an average of 6 months"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

1. ≥18 years of age inclusive, at the time of signing the informed consent.
2. Capable of giving signed informed consent.
3. Eastern Cooperative Oncology Group (ECOG) performance status of 0 to 1.
4. Patients with histologically or cytologically confirmed metastatic unresectable pancreatic adenocarcinoma.
5. Have measurable disease (≥ 1 measurable lesion) based on Response Evaluation Criteria In Solid Tumours (RECIST) v1.1 as determined by the site study team.
6. Eligible to receive 1st line systemic treatment with gemcitabine/nab-paclitaxel for metastatic disease.
7. Baseline CA19-9 levels are available from a sample acquired no more than 4 weeks prior to screening.
8. No prior systemic anti-cancer therapy for metastatic pancreatic cancer.
9. Male subjects with female partners of childbearing potential, and female subjects of child-bearing potential who had a negative serum pregnancy test at screening, must agree to use a highly effective form of contraception (with at least 99% certainty) or avoid intercourse during and upon completion of the study and for at least 3 months after the last dose of study drug.

Exclusion Criteria:

1. Inability to swallow food or any condition of the upper gastrointestinal tract that precludes administration of oral medications.
2. Have prior significant medical history and AEs:

   1. Known active CNS metastases and/or carcinomatous meningitis.
   2. History or presence of an abnormal ECG that, in the Investigator's opinion, is clinically meaningful. Screening QTc interval \> 480 milliseconds is excluded (corrected by Fridericia).
   3. Known additional malignancy that is progressing or requires active treatment. Patients with active malignancy requiring concurrent intervention or previous malignancies (for example non-melanoma skin cancers, and in situ cancers: bladder, gastric, colon, endometrial, cervical/dysplasia, melanoma or breast) unless a complete remission was achieved at least 2 years prior to study entry and no additional therapy is required during the study period.
   4. Any serious or uncontrolled medical disorder or active infection that, in the opinion of the Investigator, may increase the risk associated with study participation, study drug administration, or would impair the ability of the patient to receive protocol therapy.
3. Treatment with anticancer medications, investigational drugs, surgery and/or radiation within the following interval before the first administration of study drug:

   1. \< 14 days for chemotherapy, targeted small-molecule therapy, surgical resection of lesions or radiation therapy (prior palliative radiotherapy must have been completed at least 14 days prior to study drug administration). A 1-week washout is permitted for palliative radiation to non-CNS disease with Sponsor approval.

      Note: The use of denosumab against osteoporosis is permitted.
   2. \< 28 days for prior monoclonal antibody used for anticancer therapy with the exception of PD-1 pathway-targeted agents.
   3. \< 28 days or 5 half-lives (whichever is longer) before the first dose for all other investigational study drugs or devices. For investigational agents with long half-lives (e.g., \> 5 days), enrolment before the fifth half-life requires Medical Monitor approval.
4. Receiving an immune-suppressive based treatment for any reason (including chronic use of systemic corticosteroid at doses \> 10 mg/day prednisone equivalent) within 14 days prior to the first dose of study treatment (see the exception for CNS lesions described in 2a). Use of inhaled or topical steroids or brief corticosteroid use for radiographic procedures or systemic corticosteroids ≤ 10 mg is permitted.
5. Have received a live vaccine within 30 days of planned start of study therapy.
6. Have not recovered from toxic effect(s) of prior therapy to ≤ Grade 1, other than alopecia or fatigue.
7. Known allergy or reaction to any component of either study drug or formulation components.
8. Currently breastfeeding.
9. Known alcohol or other substance abuse.
10. Laboratory and medical history parameters not within Protocol-defined range. Absolute neutrophil count \< 1.5 × 109/L.

    1. Platelet count \< 100 × 109/L.
    2. Haemoglobin \< 8 g/dL (transfusion is acceptable to meet this criterion).
    3. Serum creatinine ≥ 1.5 × institutional ULN or measured or calculated creatinine clearance (glomerular filtration rate can also be used in place of creatinine or CrCl) \< 50 mL/min for patients with creatinine levels \> 1.5 × institutional ULN.
    4. Aspartate aminotransferase, ALT, and alkaline phosphatase (ALP) ≥ 2.5 × ULN. Note: Patients with 1) bone metastases and 2) no hepatic parenchymal metastases on screening radiographic examinations may enrol if the ALP is \< 5 × ULN. Patients with 1) bone metastases and 2) hepatic parenchymal metastases on screening radiographic examinations may enrol if the ALP is \< 5 × ULN only with Medical Monitor approval.
    5. Total bilirubin ≥ 1.5 × ULN are excluded unless direct bilirubin is ≤ ULN. If there is no institutional ULN, then direct bilirubin must be \< 40% of total bilirubin to be eligible (except patients with Gilbert syndrome - see Note below)
    6. International normalized ratio or prothrombin time (PT) \> 1.5 × ULN.
    7. Activated partial thromboplastin time (aPTT) \> 1.5 × ULN.
    8. Evidence of acute infection of hepatitis B virus (HBV), hepatitis C virus (HCV) and HIV. Patients who are on stable antiviral therapy and/or asymptomatic are eligible for the study.","healthyVolunteers":false,"sex":"ALL","minimumAge":"18 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"locations":[{"facility":"UO Oncologia of Azienda Ospedaliera Universitaria Integrata di Verona","city":"Verona","state":"Verona","zip":"37126","country":"Italy","geoPoint":{"lat":45.43854,"lon":10.9938}},{"facility":"Medical Oncology and Immunotherapy Unit, University Hospital of Siena","city":"Siena","zip":"53100","country":"Italy","geoPoint":{"lat":43.31822,"lon":11.33064}},{"facility":"Beatson West of Scotland Cancer Center","city":"Glasgow","zip":"G12 0YN","country":"United Kingdom","geoPoint":{"lat":55.86515,"lon":-4.25763}}]},"referencesModule":{"references":[{"pmid":"37278638","type":"DERIVED","citation":"Khasabova IA, Khasabov SG, Johns M, Juliette J, Zheng A, Morgan H, Flippen A, Allen K, Golovko MY, Golovko SA, Zhang W, Marti J, Cain D, Seybold VS, Simone DA. Exosome-associated lysophosphatidic acid signaling contributes to cancer pain. Pain. 2023 Dec 1;164(12):2684-2695. doi: 10.1097/j.pain.0000000000002967. Epub 2023 Jun 6."}]},"ipdSharingStatementModule":{"ipdSharing":"NO"}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-09-25"},"conditionBrowseModule":{"meshes":[{"id":"D010190","term":"Pancreatic Neoplasms"},{"id":"D009362","term":"Neoplasm Metastasis"},{"id":"D009369","term":"Neoplasms"},{"id":"D005355","term":"Fibrosis"}],"ancestors":[{"id":"D004067","term":"Digestive System Neoplasms"},{"id":"D009371","term":"Neoplasms by Site"},{"id":"D004701","term":"Endocrine Gland Neoplasms"},{"id":"D004066","term":"Digestive System Diseases"},{"id":"D010182","term":"Pancreatic Diseases"},{"id":"D004700","term":"Endocrine System Diseases"},{"id":"D009385","term":"Neoplastic Processes"},{"id":"D010335","term":"Pathologic Processes"},{"id":"D013568","term":"Pathological Conditions, Signs and Symptoms"}]},"interventionBrowseModule":{"meshes":[{"id":"D000093542","term":"Gemcitabine"},{"id":"C520255","term":"130-nm albumin-bound paclitaxel"},{"id":"D000068196","term":"Albumin-Bound Paclitaxel"}],"ancestors":[{"id":"D006571","term":"Heterocyclic Compounds"},{"id":"D003841","term":"Deoxycytidine"},{"id":"D003562","term":"Cytidine"},{"id":"D011741","term":"Pyrimidine Nucleosides"},{"id":"D011743","term":"Pyrimidines"},{"id":"D006573","term":"Heterocyclic Compounds, 1-Ring"},{"id":"D017239","term":"Paclitaxel"},{"id":"D043823","term":"Taxoids"},{"id":"D043822","term":"Cyclodecanes"},{"id":"D003516","term":"Cycloparaffins"},{"id":"D006840","term":"Hydrocarbons, Alicyclic"},{"id":"D006844","term":"Hydrocarbons, Cyclic"},{"id":"D006838","term":"Hydrocarbons"},{"id":"D009930","term":"Organic Chemicals"},{"id":"D004224","term":"Diterpenes"},{"id":"D013729","term":"Terpenes"},{"id":"D000418","term":"Albumins"},{"id":"D011506","term":"Proteins"},{"id":"D000602","term":"Amino Acids, Peptides, and Proteins"}]}},"hasResults":false},
{"protocolSection":{"identificationModule":{"nctId":"NCT06807606","orgStudyIdInfo":{"id":"2024-1605"},"secondaryIdInfos":[{"id":"NCI-2025-00794","type":"OTHER","domain":"NCI-CTRP Clinical Trials Registry"}],"organization":{"fullName":"M.D. Anderson Cancer Center","class":"OTHER"},"briefTitle":"Optimized Cord Blood Transplantation for the Treatment of Patients With High-risk Hematologic Malignancies Who Have Relapsed After First Allogeneic Stem Cell Transplantation","officialTitle":"Optimized CBT for Pts With High-risk Hematologic Malignancies Who Have Relapsed After First ASCT"},"statusModule":{"statusVerifiedDate":"2026-04","overallStatus":"RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2025-03-03","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2027-11-30","type":"ESTIMATED"},"completionDateStruct":{"date":"2029-11-30","type":"ESTIMATED"},"studyFirstSubmitDate":"2025-01-29","studyFirstSubmitQcDate":"2025-01-29","studyFirstPostDateStruct":{"date":"2025-02-04","type":"ACTUAL"},"lastUpdateSubmitDate":"2026-04-23","lastUpdatePostDateStruct":{"date":"2026-04-28","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"M.D. Anderson Cancer Center","class":"OTHER"}},"oversightModule":{"oversightHasDmc":true,"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"The goal of this clinical research study is to learn if intermediate-intensity conditioning therapy followed by a cord blood transplant can help to control high-risk hematological malignancies in patients who need a second allogeneic stem cell transplantation.","detailedDescription":"Primary Objective:

