{"protocolSection":{"identificationModule":{"nctId":"NCT01018147","orgStudyIdInfo":{"id":"MCC-10395"},"secondaryIdInfos":[{"id":"HM-10395","type":"OTHER","domain":"VCU IRB"},{"id":"CDR0000657239","type":"REGISTRY","domain":"PDQ (Physician Data Query)"},{"id":"NCI-2011-01700","type":"REGISTRY","domain":"CTRP (Clinical Trials Reporting System)"}],"organization":{"fullName":"Virginia Commonwealth University","class":"OTHER"},"briefTitle":"4D Image-guided Adaptive Radiotherapy for Lung Cancer: Patient Image Acquisition","officialTitle":"4D Image-guided Adaptive Radiotherapy for Lung Cancer: Patient Image Acquisition"},"statusModule":{"statusVerifiedDate":"2016-02","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2006-09"},"primaryCompletionDateStruct":{"date":"2012-04","type":"ACTUAL"},"completionDateStruct":{"date":"2015-10","type":"ACTUAL"},"studyFirstSubmitDate":"2009-11-20","studyFirstSubmitQcDate":"2009-11-20","studyFirstPostDateStruct":{"date":"2009-11-23","type":"ESTIMATED"},"lastUpdateSubmitDate":"2016-02-04","lastUpdatePostDateStruct":{"date":"2016-02-08","type":"ESTIMATED"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Virginia Commonwealth University","class":"OTHER"},"collaborators":[{"name":"National Cancer Institute (NCI)","class":"NIH"}]},"oversightModule":{"oversightHasDmc":true},"descriptionModule":{"briefSummary":"This clinical trial studies 4-dimensional (4-D) image-guided radiation therapy treatment planning in patients with stage I-IV non-small cell lung cancer. Computed tomography (CT) scans and treatment-planning systems may help in planning radiation therapy for patients with non-small cell lung cancer. This is not a therapy study. Therefore no direct benefit from participating is expected. However, at the discretion of the treating physician, the information gained from the additional imaging will be used to improve treatment accuracy. No patient outcome data are gathered or analyzed by this study. This study is not a:Phase I, II, or III trial, trial with "blinded" treatment arm, gene or a vaccine trial, or a multi-institutional trial.","detailedDescription":"OBJECTIVES:

* Quantify the magnitude and distribution of inter- and intrafraction anatomic variations, including the temporal stability of the tumor/respiration signal correlation.
* Improve the acquisition and reconstruction of 4D CT scan images by advancing the 4D CT scan data collection process and evaluating 4D CT scan image reconstruction using different respiratory inputs.
* Quantify the uncertainty of deformable image-registration algorithms.
* Develop and investigate the efficacy of inter- and intrafraction probabilistic planning-based 4D image-guided adaptive radiotherapy (IGART) strategies for clinical application.
* Determine the expected geometric, dosimetric, and radiobiological improvements from the 4D IGART system.

OUTLINE: Patients undergo insertion of ≥ 1 small radio-opaque marker into (or in the vicinity of) the primary lesion or suspect lymph nodes via bronchoscopy. X-rays are performed to document the position of the markers.

Patients undergo 4D CT scan before each radiotherapy session and once a week after a radiotherapy session. Patients also undergo x-ray imaging before and during radiotherapy, optical and internal marker motion recording before and after radiotherapy, and audiovisual feedback during radiotherapy.

Patients undergo image-guided adapted radiotherapy based on these data."},"conditionsModule":{"conditions":["Lung Cancer"],"keywords":["stage IIIA non-small cell lung cancer","stage IIIB non-small cell lung cancer","stage IA non-small cell lung cancer","stage IB non-small cell lung cancer","stage IIA non-small cell lung cancer","stage IIB non-small cell lung cancer"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["NA"],"designInfo":{"allocation":"NA","interventionModel":"SINGLE_GROUP","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":22,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"CT Imaging","type":"EXPERIMENTAL","description":"Patients undergo 4-D, 4-dimensional computed tomography, CT imaging prior to radiotherapy sessions and once a week at the end of treatment.","interventionNames":["Procedure: 4-dimensional computed tomography"]}],"interventions":[{"type":"PROCEDURE","name":"4-dimensional computed tomography","description":"Undergo 4-D CT imaging","armGroupLabels":["CT Imaging"],"otherNames":["4D-CT"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"At least 1 mm reduction in overall systematic error corresponding with ≥ 2 mm CTV-PTV margin reduction","timeFrame":"Up to 7 years"},{"measure":"At least 5 Gy reduction in mean lung dose","timeFrame":"up to 7 years"},{"measure":"At least 5% reduction in absolute pneumonitis risk (≥ grade 2)","timeFrame":"up to 7 years"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

