ion","armGroupLabels":["Docetaxel-PM"],"otherNames":["Nanoxel M"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Response rate as assessed by RECIST v1.1","description":"Response is confirmed at least 4 weeks later. Assessment: every 6 weeks (treatment period), every 2 months (follow-up period)","timeFrame":"2 years"}],"secondaryOutcomes":[{"measure":"Progression free survival (PFS)","description":"Assessment: every 2 months (follow-up period)","timeFrame":"2 years"},{"measure":"Disease control rate (DCR)","description":"DCR is defined as the percentage of patients who have achieved complete response, partial response and stable disease","timeFrame":"2 years"},{"measure":"Overall survival","description":"Assessment: every 2 months (follow-up period)","timeFrame":"2 years"},{"measure":"Number of participants with adverse events as assessed by CTCAE v4.0","timeFrame":"2 years"},{"measure":"Incidence rate of hypersensitivity reaction to Docetaxel-PM","timeFrame":"2 years"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

