{"protocolSection":{"identificationModule":{"nctId":"NCT05643248","orgStudyIdInfo":{"id":"NEX-20-01"},"organization":{"fullName":"Nanexa AB","class":"INDUSTRY"},"briefTitle":"To Assess Safety, Tolerability and PK of NEX-20A, a Subcutaneous Prolonged-release Injection to Healthy Subjects","officialTitle":"A Single Ascending Dose Pilot Study to Assess the Safety, Tolerability and Pharmacokinetics of NEX-20A Given as a Subcutaneous Prolonged-release Injection to Healthy Male Subjects"},"statusModule":{"statusVerifiedDate":"2023-10","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2022-11-28","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2023-09-26","type":"ACTUAL"},"completionDateStruct":{"date":"2023-09-26","type":"ACTUAL"},"studyFirstSubmitDate":"2022-11-21","studyFirstSubmitQcDate":"2022-12-01","studyFirstPostDateStruct":{"date":"2022-12-08","type":"ACTUAL"},"lastUpdateSubmitDate":"2023-10-30","lastUpdatePostDateStruct":{"date":"2023-10-31","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Nanexa AB","class":"INDUSTRY"},"collaborators":[{"name":"CTC Clinical Trial Consultants AB","class":"INDUSTRY"}]},"oversightModule":{"oversightHasDmc":true,"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"This is a single-centre, single ascending dose (SAD) pilot study designed to evaluate the safety, tolerability, including local tolerability, and pharmacokinetics (PK) of NEX-20A (lenalidomide) after the administration of a single subcutaneous prolonged-release injection to healthy male volunteers","detailedDescription":"NEX-20A will be administered in sequential cohorts, 2 standard cohorts and an optional third cohort, each comprising 3 subjects. Subjects will be dosed in a sentinel fashion, and all available safety and tolerability data up until and including 10 days for the sentinel subjects must have been eval